SELECT src.bulletin_board_id , src.bulletin_board_no , src.system_code , CASE WHEN src.bb_reply_level_depth = 0 THEN src.bulletin_board_title ELSE src.bulletin_board_title || ' (' || src.bb_reply_level_depth || ')' END AS bulletin_board_title , src.period_from_date , src.period_to_date , src.bb_top_post_flag , src.notice_type_code , code.common_code_name AS notice_type_name , src.pop_up_alarm_flag , src.hit_count , src.wrie_date , src.writer_id , src.writer_name , src.attach_flag , src.bulletin_board_level_seqs FROM ( SELECT a.bulletin_board_no , a.bulletin_board_id , a.system_code , a.bulletin_board_title , a.bulletin_board_level_seqs , TO_CHAR(a.period_from_date,'YYYY-MM-DD') AS period_from_date , TO_CHAR(a.period_to_date,'YYYY-MM-DD') AS period_to_date , a.bb_reply_level_depth , a.bulletin_board_parent_id , a.bb_top_post_flag , a.notice_type_code , a.pop_up_alarm_flag , a.bulletin_board_inquiry_count AS hit_count , a.created_by AS writer_id , NVL(b.full_name_local,b.english_full_name) AS writer_name , TO_CHAR(a.creation_date,'YYYY-MM-DD') AS wrie_date , CASE WHEN a.attach_file1_id IS NULL AND a.attach_file2_id IS NULL AND a.attach_file3_id IS NULL THEN 'N' ELSE 'Y' END attach_flag , ROWNUM as row_num FROM LGCOM_BOARD_N a , LGCOM_USER_M_V b WHERE a.bulletin_board_id = #{bulletinBoardId} AND a.delete_flag = 'N' AND a.created_by = b.application_user_id(+)
AND a.system_code = #{systemCode}
AND a.notice_type_code = #{noticeTypeCode}
AND a.bulletin_board_title LIKE #{searchKeyword} || '%'
AND DBMS_LOB.INSTR(a.bb_body_content,#{searchKeyword}) > 0
AND a.bb_top_post_flag = #{topPostFlag}
AND a.pop_up_alarm_flag = #{popupAlarmFlag}
START WITH a.bulletin_board_parent_id = 0 CONNECT BY PRIOR a.bulletin_board_no = a.bulletin_board_parent_id ORDER SIBLINGS BY NVL(a.bb_top_post_flag,'N') DESC, a.bulletin_board_parent_id DESC, a.bulletin_board_no DESC ) src , ( SELECT lc.common_code , lcm.common_code_name FROM lgcom_common_code_c lc , lgcom_common_code_multi_lang_c lcm WHERE lc.code_type_code = lcm.code_type_code AND lc.company_id = lcm.company_id AND lc.inventory_organization_id = lcm.inventory_organization_id AND lc.common_code = lcm.common_code AND lc.code_type_code = 'LGCOM_NOTICE_TYPE_CODE' AND lcm.language_code = #{USER_SESSION.languageCode} AND (apply_start_date IS NULL OR apply_start_date <= TRUNC(SYSDATE)) AND (apply_end_date IS NULL OR apply_end_date >= TO_DATE(TO_CHAR(SYSDATE,'YYYY-MM-DD') || ' 23:59:59','YYYY-MM-DD HH24:MI:SS')) AND lc.use_flag = 'Y' ) code WHERE src.notice_type_code = code.common_code(+) ORDER BY src.row_num

mapper.update:
UPDATE LGCOM_BOARD_N
   SET bulletin_board_title = #{bulletinBoardTitle}
     , bb_body_content      = #{bbBodyContent,jdbcType=CLOB}
     , period_from_date     = TO_DATE(#{periodFromDate},'YYYY-MM-DD')
     , period_to_date       = TO_DATE(#{periodToDate},'YYYY-MM-DD')
     , bb_top_post_flag     = #{bbTopPostFlag}
     , notice_type_code     = #{noticeTypeCode}
     , pop_up_alarm_flag    = #{popUpAlarmFlag}
     , last_updated_by      = #{USER_SESSION.applicationUserId}
     , last_update_date     = SYSDATE
 WHERE bulletin_board_no    = #{bulletinBoardNo}
   AND bulletin_board_id    = #{bulletinBoardId}
